function ModularInversePigeonhole(a, n):
    target <- 1 mod n
    for b in 0 .. n-1:
        if (a * b) mod n == target:
            return b            # b = L_a^{-1}(1)
    return NONE                 # a is a zero divisor

function FastPowMod(base, exp, mod):
    result <- 1; base <- base mod mod
    while exp > 0:
        if exp is odd: result <- (result*base) mod mod
        base <- (base*base) mod mod; exp <- exp >> 1
    return result
function FermatCheck(a, n):
    return FastPowMod(a, n-1, n) == 1

function PrimitiveRoot(p):
    if p == 2: return 1
    phi <- p-1; F <- distinct prime factors of phi
    for g in 2 .. p-1:
        if for all l in F: g^(phi/l) mod p != 1:
            return g
    return NONE

